import 'package:flutter/foundation.dart';import '../../../core/mesh/ble_mesh_service.dart';import '../../../core/mesh/mesh_message.dart';import '../../../core/mesh/wifi_direct_service.dart';import '../../contacts/data/contact_service.dart';class SosService {  final BleMeshService _bleMesh;  final WifiDirectService _wifiDirect;  final ContactService _contactService;  final String _myDeviceId;  SosService({    required BleMeshService bleMesh,    required WifiDirectService wifiDirect,    required ContactService contactService,    required String myDeviceId,  })  : _bleMesh = bleMesh,        _wifiDirect = wifiDirect,        _contactService = contactService,        _myDeviceId = myDeviceId {    _bleMesh.incomingMessages.listen((msg) {      if (msg.isSOS) {        _handleIncomingSos(msg);      }    });  }  Future<void> triggerSos() async {    final trusted = _contactService.getAll().where((c) => c.isTrusted).toList();    if (trusted.isEmpty) {      debugPrint('[SOS] No trusted contacts available to send SOS.');    }    final payload = "SOS EMERGENCY! Require immediate assistance.";    for (final contact in trusted) {      final msg = MeshMessage(        senderId: _myDeviceId,        senderName: "Me",        recipientId: contact.deviceId,        content: payload,        isSOS: true,      );      _bleMesh.sendMessage(msg);      _wifiDirect.sendMessage(msg);      debugPrint('[SOS] Alert sent via BLE and WiFi to ${contact.name}');    }  }  void _handleIncomingSos(MeshMessage msg) async {    debugPrint('[SOS] Incoming EMERGENCY packet from ${msg.senderId}');  }}